// Auto-generate inverse matchups
function buildBidirectionalMatchups(base: Map<string, HeroCounterMatchup[]>): Map<string, HeroCounterMatchup[]> {
  const result = new Map<string, HeroCounterMatchup[]>();

  // Copy all base entries
  for (const [heroId, matchups] of base) {
    result.set(heroId, [...matchups]);
  }

  // Add inverse entries
  for (const [sourceId, matchups] of base) {
    for (const matchup of matchups) {
      const targetId = matchup.heroId;
      let inverseAdvantage: HeroCounterMatchup['advantage'];

      if (matchup.advantage === 'Fuerte Contra') {
        inverseAdvantage = 'Débil Contra';
      } else if (matchup.advantage === 'Débil Contra') {
        inverseAdvantage = 'Fuerte Contra';
      } else {
        inverseAdvantage = 'Skill Matchup';
      }

      // Check if target already has an entry for sourceId
      const targetMatchups = result.get(targetId) ?? [];
      const alreadyExists = targetMatchups.some(m => m.heroId === sourceId);

      if (!alreadyExists) {
        targetMatchups.push({ heroId: sourceId, advantage: inverseAdvantage, reason: matchup.reason });
        result.set(targetId, targetMatchups);
      }
    }
  }

  return result;
}

export const HERO_MATCHUPS_BIDIRECTIONAL = buildBidirectionalMatchups(HERO_MATCHUPS_OVERRIDE);
